 static object Attributes(string json){try{return JsonSerializer.Deserialize<Dictionary<string,string>>(json)??new();}catch{return new Dictionary<string,string>();}}
 public async Task<object> Search(Actor a,string? text,string? selectedLayers,int page,int pageSize){a.Require("geo.read");var term=(text??"").Trim();Require(term.Length>=2,"Escriba al menos dos caracteres para buscar.");Require(page>0&&pageSize is >0 and <=100,"Paginación inválida.");var wanted=(selectedLayers??"codes,lots,blocks,roads").Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).ToHashSet(StringComparer.OrdinalIgnoreCase);Require(wanted.All(x=>Files.ContainsKey(x)),"Capa de búsqueda desconocida.");var numeric=int.TryParse(term,out var number);var rows=new List<GeoSearchItem>();
  if(wanted.Contains("codes"))rows.AddRange((await db.Set<FixedCode>().AsNoTracking().Where(x=>(numeric&&(x.CodFijo==number||x.CodF_SQL==number))||(x.CodF_SIG!=null&&x.CodF_SIG.Contains(term))||(x.Nombre!=null&&x.Nombre.Contains(term))).Take(500).ToListAsync()).Select(x=>new GeoSearchItem("codes",x.Id,x.CodFijo?.ToString()??x.CodF_SIG??$"Código {x.Id}",x.Nombre??"Código fijo",Bounds(x.Geom))));
  if(wanted.Contains("lots"))rows.AddRange((await db.Set<Lot>().AsNoTracking().Where(x=>x.NroLote!=null&&x.NroLote.Contains(term)).Take(500).ToListAsync()).Select(x=>new GeoSearchItem("lots",x.Id,x.NroLote??$"Lote {x.Id}",x.IdManzana==null?"Sin manzana vinculada":$"Manzana {x.IdManzana}",Bounds(x.Geom))));
  if(wanted.Contains("blocks"))rows.AddRange((await db.Set<Block>().AsNoTracking().Where(x=>(x.UV_MZA!=null&&x.UV_MZA.Contains(term))||(x.UV!=null&&x.UV.Contains(term))||(x.MZA!=null&&x.MZA.Contains(term))).Take(500).ToListAsync()).Select(x=>new GeoSearchItem("blocks",x.Id,x.UV_MZA??$"Manzana {x.Id}",$"UV {x.UV??"—"} · MZA {x.MZA??"—"}",Bounds(x.Geom))));
  if(wanted.Contains("roads"))rows.AddRange((await db.Set<Road>().AsNoTracking().Where(x=>(x.Nombre!=null&&x.Nombre.Contains(term))||(x.TipoVia!=null&&x.TipoVia.Contains(term))).Take(500).ToListAsync()).Select(x=>new GeoSearchItem("roads",x.Id,x.Nombre??$"Vía {x.Id}",x.TipoVia??"Vía",Bounds(x.Geom))));
  var ordered=rows.OrderBy(x=>x.Layer).ThenBy(x=>x.Label,StringComparer.OrdinalIgnoreCase).ToList();return new{total=ordered.Count,page,pageSize,items=ordered.Skip((page-1)*pageSize).Take(pageSize)};
 }
 public async Task<object> Detail(Actor a,string layer,int id){a.Require("geo.read");switch(layer){case "codes":{var x=await db.Set<FixedCode>().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw new BusinessException("Entidad SIG no encontrada.");return new{type="Feature",id=x.Id,geometry=x.Geom==null?null:Geo(x.Geom),properties=new{layer,label=x.CodFijo?.ToString()??x.CodF_SIG,idLote=x.IdLote,codFijo=x.CodFijo,codFSql=x.CodF_SQL,codFSig=x.CodF_SIG,nombre=x.Nombre,attributes=Attributes(x.OriginalJson)}};}case "lots":{var x=await db.Set<Lot>().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw new BusinessException("Entidad SIG no encontrada.");return new{type="Feature",id=x.Id,geometry=x.Geom==null?null:Geo(x.Geom),properties=new{layer,label=x.NroLote,idOrigen=x.IdOrigen,idManzana=x.IdManzana,attributes=Attributes(x.OriginalJson)}};}case "blocks":{var x=await db.Set<Block>().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw new BusinessException("Entidad SIG no encontrada.");return new{type="Feature",id=x.Id,geometry=x.Geom==null?null:Geo(x.Geom),properties=new{layer,label=x.UV_MZA,idOrigen=x.IdOrigen,uvMza=x.UV_MZA,uv=x.UV,mza=x.MZA,attributes=Attributes(x.OriginalJson)}};}case "roads":{var x=await db.Set<Road>().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id)??throw new BusinessException("Entidad SIG no encontrada.");return new{type="Feature",id=x.Id,geometry=x.Geom==null?null:Geo(x.Geom),properties=new{layer,label=x.Nombre,objectId=x.OBJECTID,tipoVia=x.TipoVia,osmId=x.OSMID,attributes=Attributes(x.OriginalJson)}};}default:throw new BusinessException("Capa desconocida.");}}
 public async Task<object> Places(Actor a,double lat,double lon,int radius,CancellationToken token){a.Require("geo.read");Require(double.IsFinite(lat)&&double.IsFinite(lon)&&lat is >=-90 and <=90&&lon is >=-180 and <=180,"Coordenadas inválidas.");Require(radius is >=100 and <=5000,"El radio debe estar entre 100 y 5.000 metros.");var key=configuration["OpenTripMap:ApiKey"];Require(!string.IsNullOrWhiteSpace(key),"OpenTripMap aún no está configurado. Defina AquaControl__OpenTripMap__ApiKey en el servidor.");var apiKey=key!;var language=configuration["OpenTripMap:Language"]??"en";Require(language.Length==2&&language.All(char.IsLetter),"Idioma OpenTripMap inválido.");var url=$"{language}/places/radius?lat={lat.ToString(CultureInfo.InvariantCulture)}&lon={lon.ToString(CultureInfo.InvariantCulture)}&radius={radius}&limit=50&format=geojson&apikey={Uri.EscapeDataString(apiKey)}";using var response=await clients.CreateClient("OpenTripMap").GetAsync(url,token);if(!response.IsSuccessStatusCode)throw new BusinessException("OpenTripMap no pudo consultar los lugares cercanos. Revise la clave y la disponibilidad del proveedor.");using var document=JsonDocument.Parse(await response.Content.ReadAsStreamAsync(token));return document.RootElement.Clone();}
 public async Task<object> Layer(Actor a,string layer,double west,double south,double east,double north){a.Require("geo.read");Require(west>=-180&&east<=180&&south>=-90&&north<=90&&west<east&&south<north,"Extensión inválida.");var box=Factory.ToGeometry(new Envelope(west,east,south,north));var features=new List<object>();const int limit=1000;
  void Add(int id,Geometry? g,object props){if(g!=null)features.Add(new{type="Feature",id,geometry=Geo(g),properties=props});}
  switch(layer){case "codes":foreach(var x in await db.Set<FixedCode>().AsNoTracking().Where(x=>x.Geom!=null&&x.Geom.Intersects(box)).OrderBy(x=>x.Id).Take(limit).ToListAsync())Add(x.Id,x.Geom,new{label=x.CodFijo?.ToString(),x.IdLote});break;
   case "lots":foreach(var x in await db.Set<Lot>().AsNoTracking().Where(x=>x.Geom!=null&&x.Geom.Intersects(box)).OrderBy(x=>x.Id).Take(limit).ToListAsync())Add(x.Id,x.Geom,new{label=x.NroLote,x.IdManzana});break;
   case "blocks":foreach(var x in await db.Set<Block>().AsNoTracking().Where(x=>x.Geom!=null&&x.Geom.Intersects(box)).OrderBy(x=>x.Id).Take(limit).ToListAsync())Add(x.Id,x.Geom,new{label=x.UV_MZA});break;
   case "roads":foreach(var x in await db.Set<Road>().AsNoTracking().Where(x=>x.Geom!=null&&x.Geom.Intersects(box)).OrderBy(x=>x.Id).Take(limit).ToListAsync())Add(x.Id,x.Geom,new{label=x.Nombre});break;
   default:throw new BusinessException("Capa desconocida.");}
  return new{type="FeatureCollection",features,truncated=features.Count==limit};
 }
}
